def transform(grid):
    W=len(grid[0]); sep=next(i for i,row in enumerate(grid) if all(x==5 for x in row))
    def comps(part):
        seen=set(); out=[]
        for r,row in enumerate(part):
            for c,v in enumerate(row):
                if v in (0,5) or (r,c) in seen: continue
                todo=[(r,c)]; seen.add((r,c)); cells=[]
                while todo:
                    y,x=todo.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        p=(y+dy,x+dx)
                        if 0<=p[0]<len(part) and 0<=p[1]<W and p not in seen and part[p[0]][p[1]]==v:
                            seen.add(p); todo.append(p)
                out.append((v,cells))
        return out
    top=comps(grid[:sep]); bot=comps(grid[sep+1:])
    def shape(cells):
        mr=min(r for r,c in cells); mc=min(c for r,c in cells)
        return frozenset((r-mr,c-mc) for r,c in cells)
    sample=shape(bot[0][1]); match=next(x for x in top if shape(x[1])==sample)
    # The output carries the one top shape congruent to the sample, recolored with its top color, above the unchanged sample.
    color,cells=match; out=[[0]*W for _ in range(9)]
    mr=min(r for r,c in cells); mc=min(c for r,c in cells)
    for r,c in cells: out[r-mr][c]=color
    h=max(r for r,c in cells)-mr+1
    bc,bcells=bot[0]; br=min(r for r,c in bcells); bcol=min(c for r,c in bcells)
    for r,c in bcells: out[h+1+r-br][c]=bc
    return out

