                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        p=(y+dy,x+dx)
                        if 0<=p[0]<len(part) and 0<=p[1]<W and p not in seen and part[p[0]][p[1]]==v:
                            seen.add(p); stack.append(p)
                result.append((v,cells))
